from kubernetes import client, config
from kubernetes.client import V1ObjectMeta, V1Deployment, V1DeploymentSpec, V1PodTemplateSpec, V1PodSpec, V1Container, V1ContainerPort, V1LabelSelector, V1Service, V1ServiceSpec, V1ServicePort
from kubernetes.client import ExtensionsV1beta1Api, ExtensionsV1beta1Ingress, ExtensionsV1beta1IngressSpec, ExtensionsV1beta1IngressRule, ExtensionsV1beta1HTTPIngressRuleValue, ExtensionsV1beta1HTTPIngressPath, ExtensionsV1beta1IngressBackend

DEPLOYMENT_NAME = "example-deployment"
SERVICE_NAME = "example-service"
INGRESS_NAME = "example-ingress"
NAMESPACE = "default"
IMAGE = "nginx:1.21"
CONTAINER_PORT = 80
SERVICE_PORT = 80
INGRESS_HOST = "example.local"
INGRESS_PATH = "/"

def create_deployment(api_instance):
    deployment = V1Deployment(
        metadata=V1ObjectMeta(name=DEPLOYMENT_NAME),
        spec=V1DeploymentSpec(
            replicas=1,
            selector=V1LabelSelector(
                match_labels={"app": DEPLOYMENT_NAME}
            ),
            template=V1PodTemplateSpec(
                metadata=V1ObjectMeta(labels={"app": DEPLOYMENT_NAME}),
                spec=V1PodSpec(
                    containers=[
                        V1Container(
                            name="main",
                            image=IMAGE,
                            ports=[V1ContainerPort(container_port=CONTAINER_PORT)]
                        )
                    ]
                )
            )
        )
    )
    api_instance.create_namespaced_deployment(
        namespace=NAMESPACE,
        body=deployment
    )

def create_service(api_instance):
    service = V1Service(
        metadata=V1ObjectMeta(name=SERVICE_NAME),
        spec=V1ServiceSpec(
            selector={"app": DEPLOYMENT_NAME},
            ports=[V1ServicePort(port=SERVICE_PORT, target_port=CONTAINER_PORT)]
        )
    )
    api_instance.create_namespaced_service(
        namespace=NAMESPACE,
        body=service
    )

def create_ingress(api_instance):
    ingress = ExtensionsV1beta1Ingress(
        metadata=V1ObjectMeta(name=INGRESS_NAME),
        spec=ExtensionsV1beta1IngressSpec(
            rules=[
                ExtensionsV1beta1IngressRule(
                    host=INGRESS_HOST,
                    http=ExtensionsV1beta1HTTPIngressRuleValue(
                        paths=[
                            ExtensionsV1beta1HTTPIngressPath(
                                path=INGRESS_PATH,
                                backend=ExtensionsV1beta1IngressBackend(
                                    service_name=SERVICE_NAME,
                                    service_port=SERVICE_PORT
                                )
                            )
                        ]
                    )
                )
            ]
        )
    )
    api_instance.create_namespaced_ingress(
        namespace=NAMESPACE,
        body=ingress
    )

def main():
    config.load_kube_config()
    apps_v1 = client.AppsV1Api()
    core_v1 = client.CoreV1Api()
    ext_v1beta1 = ExtensionsV1beta1Api()

    create_deployment(apps_v1)
    create_service(core_v1)
    create_ingress(ext_v1beta1)

if __name__ == "__main__":
    main()
```

